class Animal {}
class Dog extends Animal {}
class Puppy extends Dog {}
class Cat extends Animal {}

public class InstanceofDemo {
    public static void main(String[] args) {
        Animal a1 = new Dog();
        Animal a2 = new Puppy();
        Animal a3 = null;

        // 1. Direct class check
        System.out.println("a1 instanceof Dog: " + (a1 instanceof Dog)); // true
        System.out.println("a1 instanceof Animal: " + (a1 instanceof Animal)); // true
        System.out.println("a1 instanceof Cat: " + (a1 instanceof Cat)); // false

        // 2. Transitive subclass check
        System.out.println("a2 instanceof Animal: " + (a2 instanceof Animal)); // true
        System.out.println("a2 instanceof Dog: " + (a2 instanceof Dog)); // true

        // 3. Null safety guarantee
        System.out.println("a3 instanceof Animal: " + (a3 instanceof Animal)); // false
    }
}

