interface SystemEvent {}
class LoginEvent implements SystemEvent {
    public String username;
    public LoginEvent(String u) { this.username = u; }
}
class LogoutEvent implements SystemEvent {
    public String username;
    public LogoutEvent(String u) { this.username = u; }
}

public class EventDispatcher {
    public static void dispatch(SystemEvent event) {
        if (event instanceof LoginEvent) {
            LoginEvent le = (LoginEvent) event;
            System.out.println("AUDIT: User logged in -> " + le.username);
        } else if (event instanceof LogoutEvent) {
            LogoutEvent lo = (LogoutEvent) event;
            System.out.println("AUDIT: User logged out -> " + lo.username);
        } else {
            System.out.println("AUDIT: Unknown event received");
        }
    }

    public static void main(String[] args) {
        dispatch(new LoginEvent("alice"));
        dispatch(new LogoutEvent("bob"));
    }
}

