interface Appliance {
    String getName();
}

class AirConditioner implements Appliance {
    private String name;
    private int targetTemp;
    public AirConditioner(String name, int targetTemp) {
        this.name = name;
        this.targetTemp = targetTemp;
    }
    @Override
    public String getName() { return name; }
    public int getTargetTemp() { return targetTemp; }
}

class WashingMachine implements Appliance {
    private String name;
    private int spinSpeed;
    public WashingMachine(String name, int spinSpeed) {
        this.name = name;
        this.spinSpeed = spinSpeed;
    }
    @Override
    public String getName() { return name; }
    public int getSpinSpeed() { return spinSpeed; }
}

class ApplianceInspector {
    public static void inspect(Appliance a) {
        System.out.println("Appliance: " + a.getName());
        if (a instanceof AirConditioner) {
            AirConditioner ac = (AirConditioner) a;
            System.out.println("  Cooling to " + ac.getTargetTemp() + "C");
        } else if (a instanceof WashingMachine) {
            WashingMachine wm = (WashingMachine) a;
            System.out.println("  Spinning at " + wm.getSpinSpeed() + " RPM");
        }
    }
}

public class SmartHomeApp {
    public static void main(String[] args) {
        ApplianceInspector.inspect(new AirConditioner("Living Room AC", 22));
        ApplianceInspector.inspect(new WashingMachine("LG TurboWash", 1400));
    }
}

interface Payload {
    String getId();
}

class TextPayload implements Payload {
    private String id;
    private String text;
    public TextPayload(String id, String text) {
        this.id = id;
        this.text = text;
    }
    @Override
    public String getId() { return id; }
    public int getCharCount() { return text.length(); }
}

class BinaryPayload implements Payload {
    private String id;
    private int byteSize;
    public BinaryPayload(String id, int byteSize) {
        this.id = id;
        this.byteSize = byteSize;
    }
    @Override
    public String getId() { return id; }
    public int getByteSize() { return byteSize; }
}

class Auditor {
    public static String summarize(Payload p) {
        if (p == null) {
            return "Null or invalid payload";
        }
        if (p instanceof TextPayload) {
            TextPayload tp = (TextPayload) p;
            return "Text Payload [" + tp.getId() + "] chars: " + tp.getCharCount();
        } else if (p instanceof BinaryPayload) {
            BinaryPayload bp = (BinaryPayload) p;
            return "Binary Payload [" + bp.getId() + "] bytes: " + bp.getByteSize();
        }
        return "Generic Payload [" + p.getId() + "]";
    }
}

public class AuditApp {
    public static void main(String[] args) {
        System.out.println(Auditor.summarize(new TextPayload("p-1", "Hello World")));
        System.out.println(Auditor.summarize(new BinaryPayload("p-2", 2048)));
        System.out.println(Auditor.summarize(null));
    }
}

