class Component {}
class Container extends Component {}
class Panel extends Container {}
class Button extends Component {}

public class HierarchyApp {
    public static void main(String[] args) {
        Component[] elements = new Component[] {
            new Panel(),
            new Container(),
            new Button(),
            new Component(),
            null
        };

        int compCount = 0;
        int contCount = 0;
        int panelCount = 0;

        for (Component e : elements) {
            if (e instanceof Component) compCount++;
            if (e instanceof Container) contCount++;
            if (e instanceof Panel) panelCount++;
        }

        System.out.println("Component count: " + compCount);
        System.out.println("Container count: " + contCount);
        System.out.println("Panel count: " + panelCount);
    }
}
